*{box-sizing:border-box}.request-page{max-width:900px;margin:auto;padding:42px 30px 80px}.back{color:var(--text-muted);text-decoration:none}.title{color:var(--secondary-color);font-size:32px;margin:25px 0 8px}.sub{color:var(--text-muted);margin:0 0 28px}.request-layout{display:grid;grid-template-columns:280px 1fr;gap:28px}.target,.form-card{border:1px solid #ddd7d1;border-radius:14px;padding:20px;background:#fff}.target img{width:100%;height:300px;object-fit:contain;border-radius:10px;background:#f8f2ee}.target h2{font-size:19px;color:var(--secondary-color);margin:14px 0 5px}.target p{color:var(--text-muted);margin:5px 0}.field{margin-bottom:20px}.field label{display:block;color:var(--secondary-color);font-weight:600;margin-bottom:8px}.field select,.field textarea{width:100%;border:1px solid #d7d2cd;border-radius:9px;padding:12px;font:inherit;background:#fff}.field textarea{min-height:130px;resize:vertical}.hint{font-size:13px;color:var(--text-muted);line-height:1.6}.submit{width:100%;height:48px;border:0;border-radius:9px;background:#d3948b;color:#fff;font:inherit;font-weight:700;cursor:pointer}.notice{padding:14px 18px;border-radius:9px;margin-bottom:20px}.ok{background:#e7f4e3;color:#3d7038}.bad{background:#fde7e3;color:#9b443c}.after{display:flex;gap:10px;margin-top:12px}.after a{flex:1;text-align:center;padding:11px;border:1px solid #d3948b;border-radius:8px;color:#b66f68;text-decoration:none}@media(max-width:700px){.request-page{padding:28px 16px 60px}.request-layout{grid-template-columns:1fr}.target img{height:240px}}
</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="request-page"><a class="back" href="/pages/book_detail.php?source=exchange&amp;id=<?=$exchangeId?>">← กลับไปหน้ารายละเอียด</a><h1 class="title">ยื่นคำขอแลกเปลี่ยน</h1><p class="sub">เลือกหนังสือที่ต้องการเสนอ หรือส่งข้อความเพื่อพูดคุยรายละเอียดเพิ่มเติม</p><?php if($success):?><div class="notice ok"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($error):?><div class="notice bad"><?=htmlspecialchars($error)?></div><?php endif;?><div class="request-layout"><aside class="target"><?php if($img=erImage($target['image_cover'])):?><img src="<?=htmlspecialchars($img)?>" alt="<?=htmlspecialchars($target['title'])?>"><?php endif;?><h2><?=htmlspecialchars($target['title'])?></h2><p><?=htmlspecialchars($target['author']?:'-')?></p><p>เจ้าของ: <?=htmlspecialchars($target['owner_name'])?></p><p>สภาพ <?=number_format((int)$target['condition_percent'])?>%</p></aside><section class="form-card"><?php if(!$success):?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['exchange_request_csrf'])?>"><div class="field"><label>หนังสือที่คุณเสนอแลก</label><select name="offered_exchange_id"><option value="">ยังไม่ระบุ / ขอพูดคุยก่อน</option><?php foreach($myOffers as $offer):?><option value="<?=$offer['exchange_id']?>" <?=((int)($_POST['offered_exchange_id']??0)===(int)$offer['exchange_id'])?'selected':''?>><?=htmlspecialchars($offer['title'].(!empty($offer['author'])?' — '.$offer['author']:''))?></option><?php endforeach;?></select><?php if(!$myOffers):?><p class="hint">คุณยังไม่มีโพสต์แลกเปลี่ยนที่เปิดอยู่ สามารถส่งข้อความก่อน หรือไปลงประกาศหนังสือของคุณได้</p><?php endif;?></div><div class="field"><label>ข้อความถึงเจ้าของหนังสือ</label><textarea name="message" placeholder="แนะนำหนังสือที่ต้องการเสนอ หรือแจ้งรายละเอียดที่อยากสอบถาม..."><?=htmlspecialchars($_POST['message']??'')?></textarea></div><button class="submit" type="submit">ยืนยันยื่นคำขอแลกเปลี่ยน</button></form><?php else:?><div class="after"><a href="/pages/chat.php?seller_type=user&amp;seller_id=<?=(int)$target['owner_id']?>&amp;exchange_id=<?=$exchangeId?>">ส่งข้อความเพิ่มเติม</a><a href="/pages/exchange_books.php">กลับลานแลกเปลี่ยน</a></div><?php endif;?></section></div></main><?php require __DIR__.'/../components/footer.php';?></body></html>
